// Package shared holds code every app uses. Keep it free of HTTP or app concerns.
package shared

import "fmt"

// Greet returns a greeting for name.
func Greet(name string) string {
	return fmt.Sprintf("Hello, %s!", name)
}

package shared

import "testing"

func TestGreet(t *testing.T) {
	if got := Greet("Ana"); got != "Hello, Ana!" {
		t.Fatalf("Greet() = %q", got)
	}
}

package main

import (
	"log"
	"net/http"
	"os"
)

func main() {
	addr := ":" + envOr("PORT", "8080")
	log.Printf("API en %s", addr)
	log.Fatal(http.ListenAndServe(addr, newRouter()))
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

package main

import (
	"encoding/json"
	"net/http"

	"{{name}}/packages/shared"
)

func newRouter() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, map[string]bool{"ok": true})
	})
	mux.HandleFunc("GET /greet/{name}", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, map[string]string{"message": shared.Greet(r.PathValue("name"))})
	})
	return mux
}

func writeJSON(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(v)
}

package main

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestGreet(t *testing.T) {
	rec := httptest.NewRecorder()
	newRouter().ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/greet/Ana", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d", rec.Code)
	}
}

// The worker runs background jobs on a schedule. Replace the ticker with your queue.
package main

import (
	"context"
	"log"
	"os/signal"
	"syscall"
	"time"

	"{{name}}/packages/shared"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	ticker := time.NewTicker(time.Minute)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			log.Println(shared.Greet("worker"))
		}
	}
}
